def enable_for_formularios_clients(apps, schema_editor):
    """Clients with Formularios get the new module; it can be turned off per client."""
    Client = apps.get_model("core", "Client")
    for client in Client.objects.all():
        if "formularios" in client.enabled_modules and "aprendizaje" not in client.enabled_modules:
            client.enabled_modules = [*client.enabled_modules, "aprendizaje"]
            client.save(update_fields=["enabled_modules"])


